/* A waveform workbench for precise, selected-clip audio edits. */
const audioDesk=document.createElement('section');audioDesk.id='audio-desk';audioDesk.hidden=true;audioDesk.setAttribute('aria-label','Audio range editor');
audioDesk.innerHTML=`<header><div><span class="desk-eyebrow">AUDIO EDITOR</span><strong id="desk-name"></strong></div><button id="desk-collapse" class="secondary" title="Collapse waveform editor">Collapse</button></header><div id="desk-wave" class="desk-wave" tabindex="0" aria-label="Click to seek; drag to select an audio range"><canvas id="desk-canvas" width="1200" height="100"></canvas><div id="desk-range"></div><i id="desk-playhead"></i><span class="desk-wave-hint">Drag across the waveform to select a range</span></div><div class="desk-controls"><label>From <input id="desk-from" type="number" min="0" step=".01" aria-label="Audio range start seconds"></label><label>To <input id="desk-to" type="number" min="0" step=".01" aria-label="Audio range end seconds"></label><button id="desk-listen" class="secondary">▶ Listen to range</button><button id="desk-cut" class="secondary">✂ Delete range</button><button id="desk-keep" class="secondary">Keep range</button></div><p id="desk-status" role="status">Range edits affect this audio clip only. Delete closes its gap; other tracks keep their timing.</p>`;
$('#stage').after(audioDesk);$('.viewer-top>span').insertAdjacentHTML('beforeend','<button id="audio-desk-toggle" class="small-toggle" hidden>Audio editor</button>');
let audioDeskOpen=true,deskClipSignature=null,deskRange={from:0,to:0},deskPointer=null,deskPreview=null,deskAuditionRevision=0,deskSoundSignature=null,deskPreparing=false;
function deskClip(){const c=current();return c?.track==='audio'&&getSelectionIds().length===1?c:null;}
function deskSignature(c){return c?JSON.stringify([c.id,c.assetId,c.in,c.duration,c.speed]):null;}
function stopDeskPreview(){deskAuditionRevision++;deskPreparing=false;if(deskPreview){const preview=deskPreview;deskPreview=null;try{preview.source.stop();}catch{}preview.context.close().catch(()=>{});}$('#desk-listen').textContent='▶ Listen to range';}
function validDeskRange(){const c=deskClip();return c&&Number.isFinite(deskRange.from)&&Number.isFinite(deskRange.to)&&deskRange.from>=0&&deskRange.to<=c.duration+.000001&&deskRange.to-deskRange.from>=.05-.000001;}
function paintDeskRange(){
 const c=deskClip();if(!c)return;const valid=validDeskRange(),range=$('#desk-range');range.style.left=(deskRange.from/c.duration*100)+'%';range.style.width=(Math.max(0,deskRange.to-deskRange.from)/c.duration*100)+'%';range.hidden=!valid;
 $('#desk-from').value=Number.isFinite(deskRange.from)?deskRange.from.toFixed(2):'';$('#desk-to').value=Number.isFinite(deskRange.to)?deskRange.to.toFixed(2):'';$('#desk-listen').disabled=!valid||exporting;for(const id of ['desk-cut','desk-keep'])$('#'+id).disabled=!valid||exporting||clipLocked(c);
}
function updateAudioDesk(){
 const c=deskClip(),signature=deskSignature(c),soundSignature=JSON.stringify(c);if(soundSignature!==deskSoundSignature){stopDeskPreview();deskSoundSignature=soundSignature;}if(signature!==deskClipSignature){stopDeskPreview();deskPointer=null;deskClipSignature=signature;deskRange={from:0,to:c?.duration||0};$('#desk-status').textContent='Range edits affect this audio clip only. Delete closes its gap; other tracks keep their timing.';}
 $('#audio-desk-toggle').hidden=!c||exporting;$('#audio-desk-toggle').textContent=audioDeskOpen?'Hide waveform':'Audio editor';audioDesk.hidden=!c||!audioDeskOpen||exporting;$('.viewer').classList.toggle('audio-editing',!audioDesk.hidden);if(!c||audioDesk.hidden)return;
 $('#desk-name').textContent=c.name;$('#desk-from').max=$('#desk-to').max=c.duration;for(const id of ['desk-from','desk-to'])$('#'+id).disabled=clipLocked(c);paintDeskRange();
 const canvas=$('#desk-canvas');decodeAudioAsset(assets.get(c.assetId)).then(buffer=>{if(deskClipSignature===signature&&!audioDesk.hidden)drawWaveform(canvas,c,buffer);}).catch(()=>{$('#desk-status').textContent='This audio waveform could not be decoded. Try re-importing the file.';});
}
const deskBeforeInspector=renderInspector;
renderInspector=function(){deskBeforeInspector();updateAudioDesk();const open=$('#audio-open-editor');if(open)open.onclick=()=>{audioDeskOpen=true;updateAudioDesk();audioDesk.scrollIntoView?.({block:'nearest'});};};
$('#audio-desk-toggle').onclick=()=>{stopDeskPreview();audioDeskOpen=!audioDeskOpen;updateAudioDesk();};
$('#desk-collapse').onclick=()=>{stopDeskPreview();audioDeskOpen=false;updateAudioDesk();};
function deskTime(e){const c=deskClip(),r=$('#desk-wave').getBoundingClientRect();return clamp((e.clientX-r.left)/Math.max(1,r.width),0,1)*c.duration;}
$('#desk-wave').addEventListener('pointerdown',e=>{const c=deskClip();if(e.button!==0||!c||exporting)return;stopDeskPreview();stop();deskPointer={x:e.clientX,time:deskTime(e),signature:deskSignature(c),moved:false};try{e.currentTarget.setPointerCapture?.(e.pointerId);}catch{}e.currentTarget.focus();e.preventDefault();});
window.addEventListener('pointermove',e=>{if(!deskPointer||deskPointer.signature!==deskSignature(deskClip()))return;const p=deskPointer;if(Math.abs(e.clientX-p.x)<3&&!p.moved)return;p.moved=true;const t=deskTime(e);deskRange={from:Math.min(p.time,t),to:Math.max(p.time,t)};paintDeskRange();e.preventDefault();});
window.addEventListener('pointerup',()=>{if(!deskPointer)return;const p=deskPointer;deskPointer=null;if(!p.moved&&deskClip()){playhead=deskClip().start+p.time;updatePlayhead();syncMedia();drawFrame();}});
window.addEventListener('pointercancel',()=>deskPointer=null);window.addEventListener('blur',()=>{deskPointer=null;stopDeskPreview();});
for(const [id,key]of [['desk-from','from'],['desk-to','to']])$('#'+id).onchange=e=>{stopDeskPreview();deskRange[key]=e.target.value===''?NaN:Number(e.target.value);paintDeskRange();};
function applyDeskRange(keep){const c=deskClip();if(!c||!validDeskRange()||!requireEditable())return;stopDeskPreview();stop();let pieces;try{pieces=Model.audioRange(c,deskRange.from,deskRange.to,keep,uid);}catch(e){return toast(e.message);}checkpoint();project.clips.splice(project.clips.indexOf(c),1,...pieces);setSelection(pieces.length?[pieces[0].id]:[]);if(pieces[0])playhead=pieces[0].start;commit();updatePlayhead();toast(keep?'Kept the selected audio range.':'Audio range deleted. Other tracks kept their timing.');}
$('#desk-cut').onclick=()=>applyDeskRange(false);$('#desk-keep').onclick=()=>applyDeskRange(true);
$('#desk-listen').onclick=async()=>{
 if(deskPreview||deskPreparing){stopDeskPreview();return;}if(!validDeskRange()||exporting)return;stop();stopDeskPreview();const revision=deskAuditionRevision,signature=deskClipSignature,from=deskRange.from,to=deskRange.to;deskPreparing=true;$('#desk-listen').textContent='Preparing…';
 try{const buffer=await renderAudioBuffer(true);if(revision!==deskAuditionRevision||signature!==deskClipSignature||exporting)return;const context=new AudioContext();await context.resume();if(revision!==deskAuditionRevision){await context.close();return;}const source=context.createBufferSource();source.buffer=buffer;source.connect(context.destination);deskPreparing=false;deskPreview={context,source};source.onended=()=>{if(deskPreview?.source===source)stopDeskPreview();};source.start(0,from,to-from);$('#desk-listen').textContent='■ Stop listening';}
 catch(e){if(revision!==deskAuditionRevision)return;deskPreparing=false;$('#desk-status').textContent='Could not preview audio: '+e.message;$('#desk-listen').textContent='▶ Listen to range';}
};
// Preview-only audition must stop before playback, exporting, or replacing a project.
const toggleBeforeDesk=togglePlay;togglePlay=function(){stopDeskPreview();return toggleBeforeDesk();};$('#play').onclick=togglePlay;
const exportBeforeDesk=startExport;startExport=async function(){stopDeskPreview();return exportBeforeDesk();};$('#render-export').onclick=startExport;
const deskBeforeDraw=drawFrame;drawFrame=function(){deskBeforeDraw();const c=deskClip();if(c&&!audioDesk.hidden){const p=clamp((playhead-c.start)/c.duration,0,1);$('#desk-playhead').style.left=(p*100)+'%';}};

const libraryBeforeAudioDesk=renderLibrary;
renderLibrary=function(){libraryBeforeAudioDesk();if(tab!=='audio')return;const list=[...assets.values()].filter(a=>a.type==='audio'&&!a.id.startsWith('tone-'));if(!list.length)return;const section=document.createElement('div');section.className='imported-audio-list';section.innerHTML='<div class="section-label">Your imported audio</div>'+list.map(a=>`<button class="asset audio-file-card" draggable="true" data-asset="${a.id}" title="Drag to timeline or click to add at playhead"><span class="audio-file-icon">♫</span><span class="asset-name">${esc(a.name)}<small>${time(a.duration||0)}</small></span><span class="audio-file-add">+</span></button>`).join('');$('#library-content').prepend(section);$$('[data-asset]',section).forEach(b=>b.onclick=()=>addAsset(b.dataset.asset,playhead));};
